import type { Backup, BackupCreate, BackupUpdate } from './model';
import { BackupRepository, BackupNotFoundError } from './repository';
import { validateBackupCreate, validateBackupUpdate } from './validator';

export interface BackupServiceDeps {
  repository: BackupRepository;
  clock?: () => Date;
  logger?: (msg: string, meta?: Record<string, unknown>) => void;
}

export interface ListBackupOptions {
  offset?: number;
  limit?: number;
  sortBy?: keyof Backup;
  order?: 'asc' | 'desc';
}

/**
 * Business-logic layer above BackupRepository.
 */
export class BackupService {
  private readonly repo: BackupRepository;
  private readonly clock: () => Date;
  private readonly logger: (msg: string, meta?: Record<string, unknown>) => void;

  constructor(deps: BackupServiceDeps) {
    this.repo = deps.repository;
    this.clock = deps.clock ?? (() => new Date());
    this.logger = deps.logger ?? (() => { /* noop */ });
  }

  create(input: BackupCreate): Backup {
    const errors = validateBackupCreate(input);
    if (errors.length > 0) throw new BackupValidationError(errors);
    const created = this.repo.insert(input);
    this.logger('BackupService.create', { id: created.id });
    return created;
  }

  get(id: string): Backup {
    return this.repo.requireById(id);
  }

  tryGet(id: string): Backup | undefined {
    return this.repo.findById(id);
  }

  update(id: string, patch: BackupUpdate): Backup {
    const errors = validateBackupUpdate(patch);
    if (errors.length > 0) throw new BackupValidationError(errors);
    const updated = this.repo.update(id, patch);
    this.logger('BackupService.update', { id });
    return updated;
  }

  delete(id: string): void {
    const existed = this.repo.delete(id);
    if (!existed) throw new BackupNotFoundError(id);
    this.logger('BackupService.delete', { id });
  }

  list(options: ListBackupOptions = {}): Backup[] {
    const offset = options.offset ?? 0;
    const limit = options.limit ?? 50;
    if (options.sortBy) {
      const sorted = this.repo.sortedBy(options.sortBy, options.order);
      return sorted.slice(offset, offset + limit);
    }
    return this.repo.paginate(offset, limit);
  }

  countAll(): number {
    return this.repo.count();
  }

  batchCreate(inputs: BackupCreate[]): Backup[] {
    for (const input of inputs) {
      const errors = validateBackupCreate(input);
      if (errors.length > 0) throw new BackupValidationError(errors);
    }
    return this.repo.batchInsert(inputs);
  }

  exists(id: string): boolean {
    return this.repo.findById(id) !== undefined;
  }

  bulkDelete(ids: string[]): number {
    let deleted = 0;
    for (const id of ids) if (this.repo.delete(id)) deleted++;
    return deleted;
  }

  searchByField<K extends keyof Backup>(field: K, value: Backup[K]): Backup[] {
    return this.repo.filter((entity) => entity[field] === value);
  }
}

export class BackupServiceError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'BackupServiceError';
  }
}

export class BackupValidationError extends Error {
  constructor(public readonly errors: string[]) {
    super(`Backup validation failed: ${errors.join('; ')}`);
    this.name = 'BackupValidationError';
  }
}
